keyframes_css:
@keyframes wave-swell {
  0%   { transform: translateX(0) scaleY(1); }
  50%  { transform: translateX(-18px) scaleY(1.18); }
  100% { transform: translateX(0) scaleY(1); }
}

@keyframes wave-drift {
  0%   { transform: translateX(0); }
  50%  { transform: translateX(12px); }
  100% { transform: translateX(0); }
}

@keyframes foam-pulse {
  0%   { opacity: 0.55; transform: scaleX(1); }
  50%  { opacity: 0.85; transform: scaleX(1.08); }
  100% { opacity: 0.55; transform: scaleX(1); }
}

@keyframes sky-glow {
  0%   { opacity: 0.7; }
  50%  { opacity: 1; }
  100% { opacity: 0.7; }
}

.demo-stage {
  width: 200px;
  height: 200px;
  position: relative;
  overflow: hidden;
  background: linear-gradient(170deg, #d6e8f4 0%, #c8ddef 45%, #b8d0e8 100%);
  border-radius: 12px;
}

/* 遠景の空の光 */
.demo-stage .sky-glow {
  position: absolute;
  top: 10px;
  left: 30px;
  width: 140px;
  height: 50px;
  background: radial-gradient(ellipse, #f0e8d0 0%, transparent 70%);
  border-radius: 50%;
  animation: sky-glow 4s ease-in-out infinite;
}

/* 遠景の水平線 */
.demo-stage .horizon {
  position: absolute;
  top: 90px;
  left: 0;
  width: 200px;
  height: 6px;
  background: linear-gradient(90deg, #90b8d8, #a8c8e0, #90b8d8);
  opacity: 0.5;
  border-radius: 50%;
}

/* 波レイヤー共通 */
.demo-stage .wave {
  position: absolute;
  width: 260px;
  left: -30px;
  border-radius: 48% 52% 44% 56% / 36% 42% 58% 50%;
}

.demo-stage .wave-1 {
  height: 90px;
  bottom: 20px;
  background: linear-gradient(180deg, #7ab0d4 0%, #90b8d8 60%, #a8ccdf 100%);
  opacity: 0.9;
  animation: wave-swell 3.6s ease-in-out infinite;
}

.demo-stage .wave-2 {
  height: 76px;
  bottom: 30px;
  background: linear-gradient(180deg, #8abce0 0%, #a0cce8 55%, #b8d8ef 100%);
  opacity: 0.8;
  border-radius: 52% 48% 55% 45% / 40% 36% 60% 48%;
  animation: wave-swell 4.2s ease-in-out infinite;
  animation-delay: -1.2s;
}

.demo-stage .wave-3 {
  height: 60px;
  bottom: 44px;
  background: linear-gradient(180deg, #aad0ec 0%, #bcdaf4 50%, #cce4f8 100%);
  opacity: 0.7;
  border-radius: 55% 45% 50% 50% / 44% 50% 50% 44%;
  animation: wave-drift 5s ease-in-out infinite;
  animation-delay: -2.5s;
}

/* 泡・白波 */
.demo-stage .foam {
  position: absolute;
  height: 10px;
  background: linear-gradient(90deg, transparent, #e8f4fc, #f4f8ff, #e0eff8, transparent);
  border-radius: 50%;
  animation: foam-pulse 3.6s ease-in-out infinite;
}

.demo-stage .foam-1 {
  width: 90px;
  bottom: 106px;
  left: 20px;
  animation-delay: 0s;
}

.demo-stage .foam-2 {
  width: 60px;
  bottom: 112px;
  left: 100px;
  animation-delay: -1s;
}

.demo-stage .foam-3 {
  width: 110px;
  bottom: 98px;
  left: 10px;
  animation-delay: -2s;
}

/* 砂浜 */
.demo-stage .sand {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 200px;
  height: 28px;
  background: linear-gradient(180deg, #ddd0a8 0%, #d4c898 100%);
  border-radius: 60% 60% 0 0 / 40% 40% 0 0;
}

.demo-stage {
  width: 200px;
  height: 200px;
  position: relative;
  overflow: hidden;
  background: linear-gradient(160deg, #ede8e0 0%, #e8e0d4 50%, #e4ddd0 100%);
}

/* 地面 */
.demo-stage .ground {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 200px;
  height: 30px;
  background: linear-gradient(180deg, #c8a878 0%, #b89060 100%);
  border-radius: 60% 60% 0 0 / 20px 20px 0 0;
}

/* 木の幹 */
.demo-stage .trunk {
  position: absolute;
  bottom: 22px;
  left: 86px;
  width: 14px;
  height: 60px;
  background: linear-gradient(180deg, #9a7050 0%, #7a5030 100%);
  border-radius: 6px 6px 3px 3px;
}
.demo-stage .trunk::before {
  content: '';
  position: absolute;
  top: 20px;
  left: -8px;
  width: 10px;
  height: 30px;
  background: linear-gradient(130deg, #8a6040 0%, #7a5030 100%);
  border-radius: 4px;
  transform: rotate(-20deg);
}
.demo-stage .trunk::after {
  content: '';
  position: absolute;
  top: 15px;
  left: 10px;
  width: 10px;
  height: 28px;
  background: linear-gradient(50deg, #8a6040 0%, #7a5030 100%);
  border-radius: 4px;
  transform: rotate(18deg);
}

/* 葉の塊 */
.demo-stage .leaf-cluster {
  position: absolute;
  border-radius: 50%;
}
.demo-stage .leaf-cluster:nth-child(1) {
  width: 80px;
  height: 72px;
  background: radial-gradient(ellipse at 40% 40%, #e88040 0%, #c85820 70%);
  top: 32px;
  left: 56px;
  box-shadow: 0 4px 12px rgba(180,70,20,0.18);
  animation: sway1 4s ease-in-out infinite;
}
.demo-stage .leaf-cluster:nth-child(2) {
  width: 64px;
  height: 58px;
  background: radial-gradient(ellipse at 55% 35%, #d8b040 0%, #c08020 75%);
  top: 42px;
  left: 24px;
  box-shadow: 0 4px 10px rgba(160,100,10,0.15);
  animation: sway1 4s ease-in-out infinite;
  animation-delay: -1s;
}
.demo-stage .leaf-cluster:nth-child(3) {
  width: 68px;
  height: 60px;
  background: radial-gradient(ellipse at 45% 40%, #e06838 0%, #b84018 75%);
  top: 36px;
  left: 100px;
  box-shadow: 0 4px 10px rgba(160,50,10,0.15);
  animation: sway1 4s ease-in-out infinite;
  animation-delay: -2s;
}
.demo-stage .leaf-cluster:nth-child(4) {
  width: 56px;
  height: 50px;
  background: radial-gradient(ellipse at 50% 45%, #d88848 0%, #b06028 75%);
  top: 60px;
  left: 70px;
  box-shadow: 0 3px 8px rgba(150,80,20,0.12);
  animation: sway1 4s ease-in-out infinite;
  animation-delay: -0.5s;
}

/* 落ち葉 */
.demo-stage .fallen-leaf {
  position: absolute;
  width: 14px;
  height: 10px;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
}
.demo-stage .fallen-leaf:nth-child(1) {
  background: #d86030;
  bottom: 24px;
  left: 18px;
  transform: rotate(-18deg);
}
.demo-stage .fallen-leaf:nth-child(2) {
  background: #c89030;
  bottom: 26px;
  left: 148px;
  transform: rotate(25deg);
  width: 12px;
  height: 9px;
}
.demo-stage .fallen-leaf:nth-child(3) {
  background: #b85020;
  bottom: 28px;
  left: 100px;
  transform: rotate(-8deg);
  width: 10px;
  height: 8px;
}

/* 舞う落ち葉 */
.demo-stage .falling-leaf {
  position: absolute;
  width: 13px;
  height: 9px;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
}
.demo-stage .falling-leaf::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 6px;
  height: 1px;
  background: rgba(120,50,10,0.4);
  transform: translate(-50%, -50%);
  border-radius: 1px;
}
.demo-stage .falling-leaf:nth-child(1) {
  background: #d87038;
  top: 20px;
  left: 160px;
  animation: fall1 5s cubic-bezier(0.4,0,0.6,1) infinite;
}
.demo-stage .falling-leaf:nth-child(2) {
  background: #c89830;
  top: 10px;
  left: 30px;
  animation: fall2 6s cubic-bezier(0.4,0,0.6,1) infinite;
  animation-delay: -2s;
}
.demo-stage .falling-leaf:nth-child(3) {
  background: #c06028;
  top: 15px;
  left: 90px;
  animation: fall1 4.5s cubic-bezier(0.4,0,0.6,1) infinite;
  animation-delay: -3.5s;
}

@keyframes sway1 {
  0%   { transform: rotate(0deg) scale(1); }
  25%  { transform: rotate(2.5deg) scale(1.02); }
  50%  { transform: rotate(-1.5deg) scale(1.01); }
  75%  { transform: rotate(1.5deg) scale(1.02); }
  100% { transform: rotate(0deg) scale(1); }
}

@keyframes fall1 {
  0%   { transform: translate(0px, 0px) rotate(0deg);   opacity: 0.9; }
  20%  { transform: translate(-14px, 36px) rotate(40deg); opacity: 1; }
  50%  { transform: translate(8px, 90px) rotate(-20deg); opacity: 0.9; }
  80%  { transform: translate(-10px, 148px) rotate(55deg); opacity: 0.7; }
  100% { transform: translate(-4px, 185px) rotate(70deg); opacity: 0; }
}

@keyframes fall2 {
  0%   { transform: translate(0px, 0px) rotate(0deg);   opacity: 0.85; }
  25%  { transform: translate(18px, 48px) rotate(-35deg); opacity: 1; }
  55%  { transform: translate(-10px, 100px) rotate(30deg); opacity: 0.9; }
  85%  { transform: translate(14px, 158px) rotate(-50deg); opacity: 0.6; }
  100% { transform: translate(6px, 185px) rotate(-65deg); opacity: 0; }
}

.demo-stage {
  width: 200px;
  height: 200px;
  position: relative;
  overflow: hidden;
  background: linear-gradient(180deg, #dce8f0 0%, #c8dcea 60%, #b8d0e0 100%);
}

/* 空の光 */
.demo-stage .sky-glow {
  position: absolute;
  top: -20px;
  left: 20px;
  width: 80px;
  height: 80px;
  background: radial-gradient(circle, #f0e8d0 0%, transparent 70%);
  border-radius: 50%;
  opacity: 0.7;
  animation: skyPulse 4s ease-in-out infinite;
}

/* 水面 背景 */
.demo-stage .sea-bg {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 200px;
  height: 110px;
  background: linear-gradient(180deg, #90b8d8 0%, #78a8cc 50%, #6898bc 100%);
  border-radius: 0;
}

/* 波 1 (大) */
.demo-stage .wave-1 {
  position: absolute;
  bottom: 70px;
  left: -40px;
  width: 280px;
  height: 50px;
  background: linear-gradient(180deg, #a8ccdf 0%, #90b8d8 100%);
  border-radius: 50% 50% 0 0 / 30px 30px 0 0;
  opacity: 0.9;
  animation: waveSway1 3s ease-in-out infinite;
}
.demo-stage .wave-1::before {
  content: '';
  position: absolute;
  top: -12px;
  left: 10px;
  width: 240px;
  height: 24px;
  background: linear-gradient(180deg, #c0daea 0%, #a8ccdf 100%);
  border-radius: 50%;
  opacity: 0.85;
}

/* 波 2 (中) */
.demo-stage .wave-2 {
  position: absolute;
  bottom: 44px;
  left: -30px;
  width: 260px;
  height: 40px;
  background: linear-gradient(180deg, #98c0d8 0%, #80aace 100%);
  border-radius: 50% 50% 0 0 / 24px 24px 0 0;
  opacity: 0.88;
  animation: waveSway2 3.6s ease-in-out infinite;
}
.demo-stage .wave-2::before {
  content: '';
  position: absolute;
  top: -10px;
  left: 20px;
  width: 220px;
  height: 20px;
  background: linear-gradient(180deg, #b8d8e8 0%, #98c0d8 100%);
  border-radius: 50%;
  opacity: 0.8;
}

/* 波 3 (手前) */
.demo-stage .wave-3 {
  position: absolute;
  bottom: 20px;
  left: -20px;
  width: 240px;
  height: 36px;
  background: linear-gradient(180deg, #b0d0e4 0%, #90b8d4 100%);
  border-radius: 50% 50% 0 0 / 20px 20px 0 0;
  opacity: 0.92;
  animation: waveSway3 2.8s ease-in-out infinite;
}
.demo-stage .wave-3::before {
  content: '';
  position: absolute;
  top: -10px;
  left: 15px;
  width: 200px;
  height: 18px;
  background: linear-gradient(180deg, #cce4f0 0%, #b0d0e4 100%);
  border-radius: 50%;
  opacity: 0.85;
}

/* 白波泡 1 */
.demo-stage .foam-1 {
  position: absolute;
  bottom: 85px;
  left: 30px;
  width: 36px;
  height: 10px;
  background: rgba(255,255,255,0.75);
  border-radius: 50%;
  filter: blur(1px);
  animation: foamFade 3s ease-in-out infinite;
}

/* 白波泡 2 */
.demo-stage .foam-2 {
  position: absolute;
  bottom: 58px;
  left: 100px;
  width: 28px;
  height: 8px;
  background: rgba(255,255,255,0.65);
  border-radius: 50%;
  filter: blur(1px);
  animation: foamFade 3.6s ease-in-out 0.6s infinite;
}

/* 白波泡 3 */
.demo-stage .foam-3 {
  position: absolute;
  bottom: 34px;
  left: 60px;
  width: 22px;
  height: 7px;
  background: rgba(255,255,255,0.6);
  border-radius: 50%;
  filter: blur(1px);
  animation: foamFade 2.8s ease-in-out 1.2s infinite;
}

/* 遠景の小波ライン */
.demo-stage .ripple {
  position: absolute;
  bottom: 100px;
  left: 10px;
  width: 180px;
  height: 6px;
  border-top: 2px solid rgba(200,224,236,0.6);
  border-radius: 50%;
  animation: rippleMove 4s ease-in-out infinite;
}

@keyframes waveSway1 {
  0%   { transform: translateX(0px) scaleY(1); }
  50%  { transform: translateX(18px) scaleY(1.08); }
  100% { transform: translateX(0px) scaleY(1); }
}

@keyframes waveSway2 {
  0%   { transform: translateX(0px) scaleY(1); }
  50%  { transform: translateX(-16px) scaleY(1.1); }
  100% { transform: translateX(0px) scaleY(1); }
}

@keyframes waveSway3 {
  0%   { transform: translateX(0px) scaleY(1); }
  50%  { transform: translateX(14px) scaleY(1.07); }
  100% { transform: translateX(0px) scaleY(1); }
}

@keyframes foamFade {
  0%   { opacity: 0.7; transform: scaleX(1); }
  50%  { opacity: 1;   transform: scaleX(1.2); }
  100% { opacity: 0.7; transform: scaleX(1); }
}

@keyframes skyPulse {
  0%   { opacity: 0.6; transform: scale(1); }
  50%  { opacity: 0.85; transform: scale(1.1); }
  100% { opacity: 0.6; transform: scale(1); }
}

@keyframes rippleMove {
  0%   { transform: translateX(0px); opacity: 0.5; }
  50%  { transform: translateX(10px); opacity: 0.9; }
  100% { transform: translateX(0px); opacity: 0.5; }
}

@keyframes wave-roll {
  0%   { transform: translateX(0) scaleY(1); }
  45%  { transform: translateX(-18px) scaleY(1.18); }
  100% { transform: translateX(0) scaleY(1); }
}
@keyframes wave-sway {
  0%   { transform: translateX(0) scaleY(1); }
  50%  { transform: translateX(14px) scaleY(0.88); }
  100% { transform: translateX(0) scaleY(1); }
}
@keyframes foam-pulse {
  0%   { opacity: 0.55; transform: scaleX(1); }
  50%  { opacity: 0.9;  transform: scaleX(1.08); }
  100% { opacity: 0.55; transform: scaleX(1); }
}
@keyframes gull-float {
  0%   { transform: translateY(0) translateX(0); }
  40%  { transform: translateY(-6px) translateX(5px); }
  70%  { transform: translateY(-3px) translateX(10px); }
  100% { transform: translateY(0) translateX(0); }
}

